// pedido.mjs — composição: chama as outras camadas, sem repetir o trabalho delas.
import { calcularTotal } from './calculo.mjs';
import { formatarTotal } from './formatacao.mjs';

export function processarPedido(itens) {
  return formatarTotal(calcularTotal(itens));
}

// Passo 1: camada de dados — só ela toca na lista de pedidos.
const pedidos = [];
export function salvarPedido(pedido) { pedidos.push(pedido); return pedido; }

// Passo 2: camada de cálculo — matemática pura, sem tocar em lista nem em texto.
export function calcularTotal(itens) {
  return itens.reduce((soma, item) => soma + item.preco * item.quantidade, 0);
}

// Passo 3: camada de apresentação — número vira texto, sem tocar em cálculo.
export function formatarTotal(total) {
  return `R$ ${total.toFixed(2)}`;
}

// Passo 4: composição — orquestra as camadas na ordem certa.
export function registrarPedido(itens) {
  const total = calcularTotal(itens);      // primeiro o cálculo...
  const pedido = { itens, total };         // ...depois monta o registro...
  salvarPedido(pedido);                    // ...guarda na camada de dados...
  return { ...pedido, totalFormatado: formatarTotal(total) }; // ...e formata na saída.
}

// Passo 5: prova — a API devolve o pedido com o total já formatado.
console.log(registrarPedido([{ nome: 'Café', preco: 8, quantidade: 2 }]));
// imprime: { itens: [{ nome: 'Café', preco: 8, quantidade: 2 }], total: 16, totalFormatado: 'R$ 16.00' }
